-- The AGI Head Office employee directory, October 2026: 529 people from the file's 530 rows,
-- replacing the 354-person list imported by migration 0009 with the current one. (One stray row is
-- skipped -- see below.)
--
-- Source: "AGI ALL Employee Data - October 2026.xlsx", sheet "AGI ALL Employee Data - HQ".
-- Columns taken: Emp No, Employee Name, Designation, Department, Company Unit, Location, Floor,
-- Mobile No, Mail Address. The workbook's two derived sheets ("Existed in System" and "Need to
-- add in System") are views of this one and are not imported.
--
-- What the file brings that the directory did not have:
--   * Company Unit  -- the company or unit someone works for. It is stored twice: exactly as the
--     file gives it in `company_unit`, and as `business_unit_code` so every screen that already
--     reads a business unit (the directory, accounts, profile, the signup form) shows it. The
--     units the group did not have yet are added below.
--   * Location      -- "Head Office" for everyone but one person, kept in `site`, the column the
--     rest of the system reads as where someone collects.
--   * Floor         -- kept in `floor_no` (migration 0026).
--
-- Five rows cannot be mailed and are carried inactive but stay in the directory, exactly as
-- migration 0009 treated them (a System Admin can fix an address and switch the row back on):
--   000025 Md. Abul Kashem, 000168 J Hasan, 000398 A.Q.M. Sahiduzzaman -- no address on file
--   010744 Md. Shariful Islam -- no address on file
--   000688 Mohammed Shamsul Alam -- shares shamsul.alam2@anwargroup.net with 000636
-- The file writes that shared address as "...netshared address" (a note pasted on after a line
-- break); the address itself is used.
--
-- One row in the file is skipped: the one whose Emp No is "STF-0001" (name "Zaharabi Bhuiyain",
-- address admin@anwargroup.net). It is not a directory entry but a stray line, and it collides with
-- the IDs the app mints for staff accounts, which are "STF-0001", "STF-0002", ... (migration 0003).
-- Leaving it in would stop the first Super Admin from being created and block every staff
-- invitation. So 529 of the file's 530 rows are imported; migration 0032 removes the row from any
-- database where this migration already ran before it was corrected.
--
-- One person from the older list (018949 Sumaiya Rahman Liza) is not in this file. She is left in
-- place, active, rather than deleted: this migration refreshes the directory, and dropping somebody
-- from it is a decision for a System Admin, who can switch her off from the directory screen.

-- Business units named by the file that the group did not already have. Additive: an existing
-- code is left untouched, and nothing is retired.
on conflict (code) do nothing;

-- The file's own wording for the unit, kept next to the mapped business unit. Empty for the 348
-- people the file does not place in a company.
alter table employees add column company_unit text not null default '';

create temporary table directory_import_oct2026 (
  id           text primary key,
  name         text not null,
  email        text not null,
  phone        text not null,
  department   text not null,
  designation  text not null,
  company_unit text not null,
  unit_code    text,
  site         text not null,
  floor_no     text not null,
  active       boolean not null
);


-- Everyone in the file. Location goes into `site`; Floor into `floor_no`.
                       company_unit, business_unit_code, active)
select i.id, i.name, i.email, i.phone, i.department, i.designation, i.site,
       nullif(i.floor_no, ''), i.company_unit, i.unit_code, i.active
from directory_import_oct2026 i
on conflict (id) do update set
  name        = excluded.name,
  phone       = excluded.phone,
  department  = excluded.department,
  designation = excluded.designation,
  site        = excluded.site,
  floor_no    = excluded.floor_no,
  company_unit = excluded.company_unit,
  -- A person the file does not place in a company keeps whatever unit they already had.
  business_unit_code = coalesce(excluded.business_unit_code, employees.business_unit_code),
  -- Someone who already has an account keeps the address they sign in with and whether their
  -- account is switched on: the file is a directory, not an instruction to change access.
  company_email = case when employees.account_status is null
                       then excluded.company_email else employees.company_email end,
  active        = case when employees.account_status is null
                       then excluded.active else employees.active end,
  updated_at  = now();

-- Booking is what the directory is for, so every person holds the employee role. It grants no
-- sign-in, which needs account_status (migration 0002).
select i.id, 'employee', 'Employee Database import (October 2026)'
from directory_import_oct2026 i
on conflict do nothing;

drop table directory_import_oct2026;
